import json
from pathlib import Path
P=Path(__file__).resolve().parents[1]/'data'
def load(c):return json.loads((P/(c+'.json')).read_text())
def save(c,d):(P/(c+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2))
cache={c:load(c) for c in ['materials','collections','plants','zombies','locations']}
