 matches=[e for e in cache[cat] if e['name']==name];assert len(matches)==1,(cat,name,len(matches));e=matches[0]
 r={'original_id':id,'original_category':'Материал отдельной страницы','version':'браузерная социальная версия; платформа по источнику или не уточнена','date':date,'fields':fields,'confidence':confidence}
 e['prior_records']=[x for x in e.get('prior_records',[]) if x.get('original_id')!=id]+[r]
 if not any(x['url']==url for x in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная историческая статья'})
